#include "tom_stream.h"
#include <QCryptographicHash>
#include <QJsonDocument>
#include <QJsonParseError>
#include <QRegularExpression>
#include <limits>
#include <stdexcept>
namespace companion {namespace {void need(bool b,const char* m){if(!b)throw std::runtime_error(m);}}
void TomStream::reconnect(){line_.clear();event_.clear();id_.clear();data_.clear();afterCR_=false;stopped_=false;eventBytes_=0;}
bool TomStream::dispatch(const TomEventSink& sink){if(event_.isEmpty()&&id_.isEmpty()&&data_.isEmpty())return true;need(event_=="delta"||event_=="status"||event_=="question"||event_=="memory","Tom SSE event type");need(!id_.isEmpty()&&QRegularExpression("^[0-9]+\\z").match(QString::fromLatin1(id_)).hasMatch(),"Tom SSE sequence");bool ok=false;auto sequence=id_.toULongLong(&ok);need(ok&&sequence>0,"Tom SSE sequence range");QJsonParseError error;auto parsed=QJsonDocument::fromJson(data_,&error);need(error.error==QJsonParseError::NoError&&parsed.isObject(),"Tom SSE JSON");auto object=parsed.object();QString field=event_=="status"?"status":"text";need(object.size()==1&&object[field].isString(),"Tom SSE data schema");auto value=object[field].toString();need(value.size()<=(event_=="delta"?16384:event_=="question"?8000:event_=="memory"?4096:64)&&!value.contains(QChar(0))&&(event_=="delta"||!value.isEmpty()),"Tom SSE value limit"); /* question: what a read-answer request read, once, before its answer; memory: notes to keep, once, before the final status */auto fingerprint=QCryptographicHash::hash(event_+QJsonDocument(object).toJson(QJsonDocument::Compact),QCryptographicHash::Sha256);if(sequence<=cursor_){if(sequence==cursor_&&!lastFingerprint_.isEmpty())need(fingerprint==lastFingerprint_,"Tom SSE changed replay");return true;}need(!terminal_&&cursor_!=std::numeric_limits<quint64>::max()&&sequence==cursor_+1,"Tom SSE gap or closed stream");need(accepted_<4096&&textChars_+(event_!="status"?value.size():0)<=262144,"Tom SSE output limit");TomEvent event{sequence,QString::fromLatin1(event_),object};if(!sink(event)){stopped_=true;return false;}cursor_=sequence;lastFingerprint_=fingerprint;++accepted_;if(event_!="status")textChars_+=value.size();else terminal_=value=="completed"||value=="canceled"||value=="interrupted";return true;}
bool TomStream::line(const TomEventSink& sink){if(line_.isEmpty()){bool accepted=dispatch(sink);event_.clear();id_.clear();data_.clear();eventBytes_=0;return accepted;}eventBytes_+=line_.size();need(eventBytes_<=262144,"Tom SSE event byte limit");if(line_.startsWith(':'))return true;auto colon=line_.indexOf(':');auto name=colon<0?line_:line_.left(colon);auto value=colon<0?QByteArray{}:line_.mid(colon+1);if(value.startsWith(' '))value.remove(0,1);if(name=="event"){need(event_.isEmpty(),"Tom SSE duplicate event field");event_=value;}else if(name=="id"){need(id_.isEmpty(),"Tom SSE duplicate id field");id_=value;}else if(name=="data"){if(!data_.isEmpty())data_+='\n';data_+=value;}else if(name=="retry"){need(QRegularExpression("^[0-9]+\\z").match(QString::fromLatin1(value)).hasMatch(),"Tom SSE retry field");}else throw std::runtime_error("Tom SSE unsupported field");return true;}
bool TomStream::feed(const QByteArray& chunk,const TomEventSink& sink){need(bool(sink),"Tom SSE sink missing");if(stopped_)return false;need(chunk.size()<=2*1024*1024,"Tom SSE chunk limit");for(char c:chunk){if(afterCR_){afterCR_=false;if(c=='\n')continue;}if(c=='\r'||c=='\n'){bool accepted=line(sink);line_.clear();afterCR_=c=='\r';if(!accepted)return false;}else{need(line_.size()<131072,"Tom SSE line limit");line_+=c;}}return true;}
}
